<?php

namespace App\Http\Resources\V6\Vendor;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class ProductListResource extends JsonResource
{
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'name' => $this->name,
            'slug' => $this->slug,
            'code' => $this->code,
            'product_type' => $this->product_type,
            'thumbnail_full_url' => $this->thumbnail_full_url,
            'category_id' => $this->category_id,
            'sub_category_id' => $this->sub_category_id,
            'sub_sub_category_id' => $this->sub_sub_category_id,
            'brand_id' => $this->brand_id,
            'unit' => $this->unit,
            'unit_price' => (float) $this->unit_price,
            'discount' => (float) $this->discount,
            'discount_type' => $this->discount_type,
            'minimum_order_qty' => (int) $this->minimum_order_qty,
            'current_stock' => (int) $this->current_stock,
            'shipping_cost' => (float) $this->shipping_cost,
            'temp_shipping_cost' => (float) $this->temp_shipping_cost,
            'is_shipping_cost_updated' => (int) $this->is_shipping_cost_updated,
            'status' => (int) $this->status,
            'request_status' => (int) $this->request_status,
            'denied_note' => $this->denied_note,
            'created_at' => $this->created_at,
            'updated_at' => $this->whenHas('updated_at', fn () => $this->updated_at),
            'business_module' => $this->whenHas('business_module'),
            'shop_id' => $this->whenHas('shop_id', fn () => $this->shop_id),
            'category_ids' => $this->whenHas('category_ids', fn () => json_decode((string) $this->getRawOriginal('category_ids'), true) ?? []),
            'images' => $this->whenHas('images', fn () => json_decode((string) $this->getRawOriginal('images'), true) ?? []),
            'attributes' => $this->whenHas('attributes', fn () => array_map('intval', json_decode((string) $this->getRawOriginal('attributes'), true) ?? [])),
            'details' => $this->whenHas('details', fn () => $this->details),
            'featured_status' => $this->whenHas('featured_status', fn () => $this->featured_status),
            'meta_title' => $this->whenHas('meta_title', fn () => $this->meta_title),
            'meta_description' => $this->whenHas('meta_description', fn () => $this->meta_description),
            'meta_image_full_url' => $this->whenHas('meta_image', fn () => $this->meta_image_full_url),
            'multiply_qty' => $this->whenHas('multiply_qty', fn () => $this->multiply_qty),
            'video_provider' => $this->whenHas('video_provider'),
            'video_url' => $this->whenHas('video_url'),
            'digital_product_file_types' => $this->retailDetail?->digital_product_file_types,
            'digital_product_extensions' => $this->retailDetail?->digital_product_extensions,
            'preview_file_full_url' => $this->preview_file_full_url,
            'flash_deal' => $this->retailDetail?->flash_deal,
            'color_image' => json_decode((string) $this->retailDetail?->color_image, true) ?? [],
            'colors_formatted' => $this->whenHas('colors_formatted'),
            'is_shop_temporary_close' => $this->is_shop_temporary_close,
            'seo_info' => $this->whenLoaded('seoInfo'),
            'digital_product_authors' => $this->whenLoaded('digitalProductAuthors', fn () => $this->digitalProductAuthors->map(fn ($row) => [
                'id' => $row->id,
                'author_id' => $row->author_id,
                'product_id' => $row->product_id,
                'created_at' => $row->created_at,
                'updated_at' => $row->updated_at,
            ])->values()),
            'digital_product_publishing_house' => $this->whenLoaded('digitalProductPublishingHouse', fn () => $this->digitalProductPublishingHouse->map(fn ($row) => [
                'id' => $row->id,
                'publishing_house_id' => $row->publishing_house_id,
                'product_id' => $row->product_id,
                'created_at' => $row->created_at,
                'updated_at' => $row->updated_at,
            ])->values()),
            'featured' => $this->whenLoaded('retailDetail', fn () => (bool) $this->retailDetail?->featured),
            'added_by' => $this->added_by,
            'user_id' => $this->user_id,
            'thumbnail' => $this->thumbnail,
            'images_full_url' => $this->whenHas('images', fn () => $this->images_full_url),
            'color_images_full_url' => $this->color_images_full_url,
            'colors' => $this->whenHas('colors', fn () => json_decode((string) $this->getRawOriginal('colors'), true) ?? []),
            'choice_options' => $this->whenHas('choice_options', fn () => json_decode((string) $this->getRawOriginal('choice_options'), true) ?? []),
            'variation' => json_decode((string) $this->retailDetail?->variation, true) ?? [],
            'tax' => $this->tax,
            'tax_type' => $this->tax_type,
            'tax_model' => $this->tax_model,
            'digital_product_type' => $this->retailDetail?->digital_product_type,
            'reviews_count' => $this->whenHas('reviews_count', fn ($count) => (int) $count),
            'ratings_average' => $this->whenHas('ratings_average'),
            'total_qty_sold' => $this->whenHas('total_qty_sold', fn ($quantity) => (int) $quantity),
            'total_sold_amount' => $this->whenHas('totalSoldAmount', fn ($amount) => (float) $amount),
            'digital_product_authors_names' => $this->whenHas('digital_product_authors_names'),
            'digital_product_publishing_house_names' => $this->whenHas('digital_product_publishing_house_names'),
            'rating' => $this->whenLoaded('rating', fn () => $this->rating->map(fn ($rating) => [
                'average' => $rating->average,
                'product_id' => $rating->product_id,
            ])->values()),
            'brand' => $this->whenLoaded('brand', fn () => $this->brand === null ? null : ['id' => $this->brand->id, 'name' => $this->brand->name]),
            'category' => $this->whenLoaded('category', fn () => $this->category === null ? null : ['id' => $this->category->id, 'name' => $this->category->name]),
            'digital_variation' => $this->whenLoaded('digitalVariation', fn () => $this->digitalVariation->map(fn ($variation) => [
                'id' => $variation->id,
                'variant_key' => $variation->variant_key,
                'sku' => $variation->sku,
                'price' => $variation->price,
            ])->values()),
            'clearance_sale' => $this->whenLoaded('clearanceSale'),
            'tax_vats' => $this->whenLoaded('taxVats', fn () => $this->taxVats->map(fn ($taxVat) => [
                'id' => $taxVat->id,
                'tax_id' => $taxVat->tax_id,
                'tax' => $taxVat->relationLoaded('tax') ? $taxVat->tax : null,
            ])->values()),
        ];
    }
}
